import { describe, expect, it } from 'vitest';
import { GitHubReleases, LITE_GITHUB_REPO, liteZipName } from './adapter.ts';
import type { CommandResult, CommandRunner } from './adapter.ts';

const released = JSON.stringify( {
	tagName: '4.17.5',
	url: 'https://github.com/awesomemotive/wp-simple-pay-lite/releases/tag/4.17.5',
	publishedAt: '2026-10-14T14:15:46Z',
	isDraft: false,
	assets: [ { name: 'stripe-4.17.5.zip' } ],
} );

function counting( results: CommandResult[] ): { run: CommandRunner; calls: string[][] } {
	const calls: string[][] = [];
	const run: CommandRunner = async ( command, args ) => {
		calls.push( [ command, ...args ] );

		return results[ Math.min( calls.length - 1, results.length - 1 ) ];
	};

	return { run, calls };
}

describe( 'GitHubReleases', () => {
	it( 'reads a published release with its assets, asking the Lite repo by name', async () => {
		const { run, calls } = counting( [ { ok: true, stdout: released, stderr: '' } ] );

		expect( await new GitHubReleases( '/repo', run ).lookup( LITE_GITHUB_REPO, '4.17.5' ) ).toEqual( {
			exists: true,
			tag: '4.17.5',
			url: 'https://github.com/awesomemotive/wp-simple-pay-lite/releases/tag/4.17.5',
			publishedAt: '2026-10-14T14:15:46Z',
			isDraft: false,
			assets: [ 'stripe-4.17.5.zip' ],
		} );
		expect( calls[ 0 ] ).toEqual( expect.arrayContaining( [ 'gh', 'release', 'view', '4.17.5', '--repo', LITE_GITHUB_REPO ] ) );
	} );

	it( 'tells a missing release apart from a failed lookup', async () => {
		const missing = counting( [ { ok: false, stdout: '', stderr: 'release not found' } ] );
		const offline = counting( [ { ok: false, stdout: '', stderr: 'error connecting to api.github.com' } ] );
		const garbled = counting( [ { ok: true, stdout: 'not json', stderr: '' } ] );

		expect( await new GitHubReleases( '/repo', missing.run ).lookup( LITE_GITHUB_REPO, '4.17.6' ) ).toEqual( { exists: false, tag: '4.17.6' } );
		expect( await new GitHubReleases( '/repo', offline.run ).lookup( LITE_GITHUB_REPO, '4.17.6' ) ).toBeNull();
		expect( await new GitHubReleases( '/repo', garbled.run ).lookup( LITE_GITHUB_REPO, '4.17.6' ) ).toBeNull();
	} );

	it( 'copes with a release that has no assets or date', async () => {
		const { run } = counting( [ { ok: true, stdout: JSON.stringify( { tagName: '4.17.5', url: 'u', publishedAt: '', isDraft: true } ), stderr: '' } ] );

		expect( await new GitHubReleases( '/repo', run ).lookup( LITE_GITHUB_REPO, '4.17.5' ) ).toMatchObject( { exists: true, publishedAt: null, isDraft: true, assets: [] } );
	} );

	it( 'caches a lookup until it expires or is cleared', async () => {
		let now = 0;
		const { run, calls } = counting( [ { ok: true, stdout: released, stderr: '' } ] );
		const github = new GitHubReleases( '/repo', run, 1000, () => now );

		await github.lookup( LITE_GITHUB_REPO, '4.17.5' );
		await github.lookup( LITE_GITHUB_REPO, '4.17.5' );
		expect( calls ).toHaveLength( 1 );

		now = 1500;
		await github.lookup( LITE_GITHUB_REPO, '4.17.5' );
		expect( calls ).toHaveLength( 2 );

		github.clear();
		await github.lookup( LITE_GITHUB_REPO, '4.17.5' );
		expect( calls ).toHaveLength( 3 );
	} );

	it( 'does not cache a failed lookup', async () => {
		const { run, calls } = counting( [
			{ ok: false, stdout: '', stderr: 'timeout' },
			{ ok: true, stdout: released, stderr: '' },
		] );
		const github = new GitHubReleases( '/repo', run );

		expect( await github.lookup( LITE_GITHUB_REPO, '4.17.5' ) ).toBeNull();
		expect( await github.lookup( LITE_GITHUB_REPO, '4.17.5' ) ).toMatchObject( { exists: true } );
		expect( calls ).toHaveLength( 2 );
	} );

	it( 'treats a runner that throws as a failed lookup, without an unhandled rejection', async () => {
		const unhandled: unknown[] = [];
		const onUnhandled = ( reason: unknown ) => unhandled.push( reason );
		let calls = 0;
		const github = new GitHubReleases( '/repo', async () => {
			calls++;
			throw new Error( 'spawn gh ENOENT' );
		} );

		process.on( 'unhandledRejection', onUnhandled );

		try {
			expect( await github.lookup( LITE_GITHUB_REPO, '4.17.5' ) ).toBeNull();
			await new Promise( ( resolve ) => setTimeout( resolve, 10 ) );
			expect( unhandled ).toEqual( [] );
			// The failure was not cached.
			expect( await github.lookup( LITE_GITHUB_REPO, '4.17.5' ) ).toBeNull();
			expect( calls ).toBe( 2 );
		} finally {
			process.off( 'unhandledRejection', onUnhandled );
		}
	} );

	it( 'names the Lite zip the way the release commands do', () => {
		expect( liteZipName( '4.17.5' ) ).toBe( 'stripe-4.17.5.zip' );
	} );
} );
